WITH parsed AS (SELECT id, host, log_ts, payload_json, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, CAST((status_code & 8) != 0 AS INT) AS is_flagged, COALESCE(context['trace'], 'none') AS trace_or_default, COALESCE(context['version'], 'unknown') AS version_or_default, COALESCE(context['region'], 'direct') AS region_or_default FROM app_logs) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, CASE WHEN is_flagged >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_flagged_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, COUNT(CASE WHEN host = 'h3' THEN 1 END) AS h3_count FROM parsed GROUP BY DATE_TRUNC('DAY', log_ts), CASE WHEN is_flagged >= 1 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('HOUR', log_ts)
